class TextEditor {
    StringBuilder left=new StringBuilder(),right=new StringBuilder();
    public TextEditor(){
    }
    public void addText(String text){
        left.append(text);
    }
    public int deleteText(int k){
        int removed=Math.min(k,left.length());
        left.setLength(left.length()-removed);
        return removed;
    }
    private String view(){
        return left.substring(Math.max(0,left.length()-10));
    }
    public String cursorLeft(int k){
        while(k-->0&&left.length()>0){
            right.append(left.charAt(left.length()-1));
            left.setLength(left.length()-1);
        }
        return view();
    }
    public String cursorRight(int k){
        while(k-->0&&right.length()>0){
            left.append(right.charAt(right.length()-1));
            right.setLength(right.length()-1);
        }
        return view();
    }
}

code.kotlin:
class TextEditor {
    private val left=StringBuilder();
    private val right=StringBuilder();
    fun addText(text:String){
        left.append(text)
    }
    fun deleteText(k:Int):Int{
        val removed=minOf(k,left.length);
        left.setLength(left.length-removed);
        return removed
    }
    private fun view()=left.substring(maxOf(0,left.length-10));
    fun cursorLeft(kValue:Int):String{
        var k=kValue;
        while(k>0&&left.isNotEmpty()){
            right.append(left[left.length-1]);
            left.setLength(left.length-1);
            k--
        };
        return view()
    }
    fun cursorRight(kValue:Int):String{
        var k=kValue;
        while(k>0&&right.isNotEmpty()){
            left.append(right[right.length-1]);
            right.setLength(right.length-1);
            k--
        };
        return view()
    }
}

